        {
          "section_id": ".specs/features/008-settings-cli/spec.md:L231-L235",
          "excerpt": "The domains microphones, replacements, vocabulary, shortcuts, prompts, destination and the new output settings (smart paste method, automatic Enter) are added on this framework by the features that own them (001–007, 009, 010)."
        }
      ],
      "plan_citations": [],
      "searched_plan_sections": []
    },
    {
